# Check connectivity again more carefully - maybe 8-connectivity matters?
from collections import defaultdict

visited = set()
clusters_by_cc = []

def get_component(grid, r, c, rows, cols):  # 4-connectivity
    comp = [(r,c)]
    stack = [(r,c)]
    while stack:
        cr, cc_pos = stack.pop()
        for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
            nr, nc = cr+dr, cc_pos+dc
            if 0 <= nr < len(grid) and 0 <= nc < cols:
                if (nr, nc) not in visited and grid[nr][nc] == grid[r][c]:
                    visited.add((nr, nc))
                    comp.append((nr, nc))
                    stack.append((nr, nc))
    return comp

for r in range(rows):
    line_parts = demo_lines[r].split()
    for c in range(len(line_parts)):
        color = int(line_parts[c])
        if color == 7 and (r,c) not in visited:
            comp = get_component(demo_lines, r, c, rows, cols)
            mr, mr2 = min(x[0] for x in comp), max(x[0] for x in comp)
            mc, mc2 = min(x[1] for x in comp), max(x[1] for x in comp)
            clusters_by_cc.append({
                'positions': sorted(comp),
                'hsize': mc2-mc+1, 'vsize': mr2-mr+1,
                'area': len(comp)
            })

print(f"Found {len(clusters_by_cc)} clusters of 7 (4-connectivity)")
for i, clust in enumerate(clusters_by_cc):
